export function getIconSvg(name: string): string {
  if (!name) return '';
  const cleanName = name.trim();
  
  // Direct lookup
  if (streamlineIcons[cleanName]) return streamlineIcons[cleanName];

  // Alias lookup
  if (iconAliases[cleanName] && streamlineIcons[iconAliases[cleanName]]) {
    return streamlineIcons[iconAliases[cleanName]];
  }

  // Normalized kebab-case lookup
  const kebab = cleanName
    .replace(/([a-z0-9])([A-Z])/g, '$1-$2')
    .replace(/[\s_]+/g, '-')
    .toLowerCase();
  if (streamlineIcons[kebab]) return streamlineIcons[kebab];
  if (iconAliases[kebab] && streamlineIcons[iconAliases[kebab]]) {
    return streamlineIcons[iconAliases[kebab]];
  }

  // Fallback to dot or empty
  return streamlineIcons['target'] || '';
}
